"""Cookie export hardening: domain allowlist, 0600 atomic writes, refresh flow."""

import os
import shutil
import sqlite3
import stat
import subprocess
import sys
from pathlib import Path

import pytest

import export_cookies

REPO_ROOT = Path(__file__).resolve().parent.parent

FULL_JAR = """# Netscape HTTP Cookie File
# This file is generated by yt-dlp.  Do not edit.

.youtube.com\tTRUE\t/\tTRUE\t1999999999\tSID\tyt-secret
#HttpOnly_.google.com\tTRUE\t/\tTRUE\t1999999999\tHSID\tgoogle-secret
www.youtube.com\tFALSE\t/\tTRUE\t1999999999\tPREF\tf1
.midway-auth.amazon.com\tTRUE\t/\tTRUE\t1999999999\tsession\tmidway-secret
#HttpOnly_.console.aws.amazon.com\tTRUE\t/\tTRUE\t1999999999\taws-creds\taws-secret
.notgoogle.com\tTRUE\t/\tFALSE\t1999999999\ttrk\tx
.google.com.evil.example\tTRUE\t/\tFALSE\t1999999999\ttrk\ty
"""


def _mode(path) -> int:
    return stat.S_IMODE(os.stat(path).st_mode)


@pytest.mark.parametrize(
    ("host", "allowed"),
    [
        (".youtube.com", True),
        ("youtube.com", True),
        ("www.youtube.com", True),
        ("#HttpOnly_.google.com", True),
        ("accounts.google.com", True),
        ("rr1.googlevideo.com", True),
        (".notgoogle.com", False),
        ("evilyoutube.com", False),
        (".google.com.evil.example", False),
        (".midway-auth.amazon.com", False),
    ],
)
def test_is_allowed_host(host, allowed):
    assert export_cookies.is_allowed_host(host) is allowed


class TestFilterCookieFile:
    def test_keeps_only_youtube_google_cookies(self, tmp_path):
        jar = tmp_path / "cookies.txt"
        jar.write_text(FULL_JAR)
        jar.chmod(0o644)

        assert export_cookies.filter_cookie_file(str(jar)) == 3

        text = jar.read_text()
        assert text.startswith("# Netscape HTTP Cookie File\n")
        assert "yt-secret" in text and "google-secret" in text and "PREF" in text
        for leaked in ("midway-secret", "aws-secret", "notgoogle", "evil.example"):
            assert leaked not in text
        assert _mode(jar) == 0o600

    def test_leaves_no_temp_files(self, tmp_path):
        jar = tmp_path / "cookies.txt"
        jar.write_text(FULL_JAR)
        export_cookies.filter_cookie_file(str(jar))
        assert sorted(p.name for p in tmp_path.iterdir()) == ["cookies.txt"]

    def test_main_filter_exit_codes(self, tmp_path, capsys):
        jar = tmp_path / "cookies.txt"
        jar.write_text(FULL_JAR)
        assert export_cookies.main(["--filter", str(jar)]) == 0
        assert "Kept 3" in capsys.readouterr().out

        jar.write_text("# Netscape HTTP Cookie File\n.amazon.com\tTRUE\t/\tTRUE\t1\ta\tb\n")
        assert export_cookies.main(["--filter", str(jar)]) == 1
        assert export_cookies.main(["--filter"]) == 2


class TestFirefoxExport:
    @pytest.fixture
    def firefox(self, tmp_path, monkeypatch):
        profile = tmp_path / "profiles" / "abc.default-release"
        profile.mkdir(parents=True)
        conn = sqlite3.connect(profile / "cookies.sqlite")
        conn.execute(
            "CREATE TABLE moz_cookies (host TEXT, name TEXT, value TEXT, path TEXT, "
            "expiry INTEGER, isSecure INTEGER, isHttpOnly INTEGER)"
        )
        conn.executemany(
            "INSERT INTO moz_cookies VALUES (?, ?, ?, '/', 1999999999, 1, 0)",
            [(".youtube.com", "SID", "yt"), (".notgoogle.com", "trk", "x"), (".google.com", "HSID", "g")],
        )
        conn.commit()
        conn.close()
        monkeypatch.setattr(export_cookies, "FIREFOX_PROFILES_DIR", tmp_path / "profiles")
        return tmp_path

    def test_exports_exact_domains_with_private_mode(self, firefox):
        out = firefox / "cookies.txt"
        assert export_cookies.export_cookies(str(out)) == 2
        text = out.read_text()
        assert ".youtube.com\tTRUE\t/\tTRUE\t1999999999\tSID\tyt" in text
        assert "notgoogle" not in text
        assert _mode(out) == 0o600

    def test_no_allowed_cookies_writes_nothing(self, firefox, monkeypatch):
        conn = sqlite3.connect(next((firefox / "profiles").iterdir()) / "cookies.sqlite")
        conn.execute("DELETE FROM moz_cookies WHERE host != '.notgoogle.com'")
        conn.commit()
        conn.close()
        out = firefox / "cookies.txt"
        assert export_cookies.export_cookies(str(out)) == 0
        assert not out.exists()


class TestRefreshCookiesScript:
    """Runs refresh_cookies.sh with a stub interpreter that fakes yt-dlp."""

    @pytest.fixture
    def run_refresh(self, tmp_path):
        shutil.copy(REPO_ROOT / "refresh_cookies.sh", tmp_path / "refresh_cookies.sh")
        (tmp_path / "src").mkdir()
        shutil.copy(REPO_ROOT / "src" / "export_cookies.py", tmp_path / "src" / "export_cookies.py")
        (tmp_path / "jar.txt").write_text(FULL_JAR)
        stub = tmp_path / ".venv" / "bin" / "python3"
        stub.parent.mkdir(parents=True)
        stub.write_text(
            "#!/bin/bash\n"
            'if [ "$1" = "-m" ] && [ "$2" = "yt_dlp" ]; then\n'
            '  [ -n "${FAKE_YTDLP_FAIL:-}" ] && exit 1\n'
            '  while [ $# -gt 0 ]; do [ "$1" = "--cookies" ] && cp "$JAR" "$2"; shift; done\n'
            "  exit 0\n"
            "fi\n"
            f'exec "{sys.executable}" "$@"\n'
        )
        stub.chmod(0o755)

        def run(**env):
            return subprocess.run(
                ["bash", str(tmp_path / "refresh_cookies.sh")],
                capture_output=True,
                text=True,
                timeout=60,
                env={**os.environ, "JAR": str(tmp_path / "jar.txt"), "HOME": str(tmp_path), **env},
            )

        return run, tmp_path

    def test_chrome_jar_is_filtered_and_private(self, run_refresh):
        run, root = run_refresh
        result = run()
        assert result.returncode == 0, result.stdout + result.stderr
        cookies = root / "cookies.txt"
        assert "yt-secret" in cookies.read_text()
        assert "midway-secret" not in cookies.read_text()
        assert _mode(cookies) == 0o600
        assert not list(root.glob(".cookies-*"))

    def test_failed_refresh_keeps_existing_cookies(self, run_refresh):
        run, root = run_refresh
        existing = root / "cookies.txt"
        existing.write_text("previous-good-cookies")
        result = run(FAKE_YTDLP_FAIL="1")
        assert result.returncode == 1
        assert "Trying Firefox" in result.stdout
        assert existing.read_text() == "previous-good-cookies"
        assert not list(root.glob(".cookies-*"))
